  if (shouldRunLLM && !isHeartbeat) {
    console.log(`[HealthMonitor] Tier 2 (LLM) starting — ${cycleTime}`);
    llmResult = await analyzeWithLLM(checks, cycleTime);
    if (llmResult) {
      console.log(
